package conformance
import("fmt";"github.com/kakon77777-commits/isql-origin-go/sections";"github.com/kakon77777-commits/isql-origin-go/wire")
func ValidateP23(obj wire.OMIR)[]string{errs:=[]string{};by:=sectionMap(obj);invariants:=map[wire.Ref]bool{};charts:=map[wire.Ref]bool{};if p,ok:=by[8];ok{inv,e:=sections.DecodeInvariantContracts(p);if e!=nil{errs=append(errs,"P0_SECTION_DECODE_FAILED:8")}else{for _,x:=range inv{invariants[x.Invariant]=true}}};if p,ok:=by[2];ok{xs,e:=sections.DecodeSemanticCharts(p);if e!=nil{errs=append(errs,"P2_SECTION_DECODE_FAILED:2")}else{for _,x:=range xs{charts[x.Chart]=true}}};if p,ok:=by[3];ok{xs,e:=sections.DecodeTransitions(p);if e!=nil{errs=append(errs,"P2_SECTION_DECODE_FAILED:3")}else{for _,x:=range xs{if !charts[x.SourceChart]||!charts[x.TargetChart]{errs=append(errs,fmt.Sprintf("P2_TRANSITION_CHART_REF_UNKNOWN:%d:%d",x.Transition.BundleSlot,x.Transition.LocalID))};for _,r:=range append(append([]wire.Ref{},x.Preserved...),x.Lost...){if !invariants[r]{errs=append(errs,fmt.Sprintf("P2_TRANSITION_INVARIANT_REF_UNKNOWN:%d:%d",r.BundleSlot,r.LocalID))}}}}};if p,ok:=by[4];ok{xs,e:=sections.DecodeOperators(p);if e!=nil{errs=append(errs,"P3_SECTION_DECODE_FAILED:4")}else{for _,x:=range xs{for _,r:=range x.InvariantObligations{if !invariants[r]{errs=append(errs,fmt.Sprintf("P3_OPERATOR_INVARIANT_REF_UNKNOWN:%d:%d",r.BundleSlot,r.LocalID))}}}}};if p,ok:=by[5];ok{if _,e:=sections.DecodeAuthorities(p);e!=nil{errs=append(errs,"P3_SECTION_DECODE_FAILED:5")}};return errs}
